function t(t){return`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}-${String(t.getDate()).padStart(2,"0")}`}function e(t){if(!t)return null;const e=t.includes("T")?t:t.replace(" ","T"),n=new Date(e);return Number.isNaN(n.getTime())?null:n}function n(t){const n=e(t);if(!n)return"";return new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:!1}).format(n).replace(/\//g,"-")}function i(t){const n=e(t);if(!n)return"";return new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit"}).format(n).replace(/\//g,"-")}function r(t){const n=e(t);if(!n)return"";return new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",hour:"2-digit",minute:"2-digit",hour12:!1}).format(n)}export{i as a,r as b,n as c,t as f};
